import csv
obs={2:1,3:2,4:3,5:4,6:5,7:7,8:8,9:9,11:11,12:13,14:15,15:16,16:17,18:19,19:21,21:23,22:24,23:25,25:27,26:28,28:30,29:31,30:32,32:35,33:36,35:38,36:39,37:40,39:42,40:43,42:45,43:46,44:47,46:50,47:51,49:53,50:54,51:55,53:57,54:58,56:60,57:61,58:63,60:65,61:66,63:68,64:69,65:70,67:72,68:73,70:75,10:10,13:14,17:18,20:22}
# some values 10,13,17,20 from .05 sweep may be valid
rows=list(csv.DictReader(open('/tmp/metrics.tsv'),delimiter='\t'))
for r in rows:
    for k in r: r[k]=int(r[k])
features=[k for k in rows[0] if k!='size']
best=[]
# target = p*ch+q over integers scales? Search feature scaled by divisor? We can search target as alpha*ch + beta where feature value compared: first size with feat >= (a*ch+b)/c  etc. brute a/c rational via a=1..5 c=1..5 b=-20..20 (scaled by c? implement feat*c >= a*ch+b)
for feat in features:
  vals=[r[feat] for r in rows]
  for mode in ['first>=','first>','last<=','last<']:
    for a in range(0,11):
      for c in range(1,11):
        # speed reduce a/c maybe up to
        for b in range(-50,51):
          ok=0; tot=0
          for ch,exp in obs.items():
            # inequality feat ? (a*ch+b)/c => feat*c ? a*ch+b
            cand=None
            if mode.startswith('first'):
              for r in rows:
                lhs=r[feat]*c; rhs=a*ch+b
                if (mode=='first>=' and lhs>=rhs) or (mode=='first>' and lhs>rhs): cand=r['size']; break
            else:
              for r in rows:
                lhs=r[feat]*c; rhs=a*ch+b
                if (mode=='last<=' and lhs<=rhs) or (mode=='last<' and lhs<rhs): cand=r['size']
                else:
                  # feature monotonic generally, can break maybe string widths monotonic
                  pass
            tot+=1; ok+= (cand==exp)
          if ok>=len(obs)-5:
            best.append((ok,feat,mode,a,c,b))
best.sort(reverse=True)
print(best[:100])
PY"}

