{"command":"cat > src/TextGrid.java <<'EOF'
import java.awt.Color;
import java.io.*;
import java.util.*;

class TextGrid {
    int width, height;
    char[][] cells;      // padded, after colour/tag removal
    char[][] original;   // padded, before colour/tag removal

    static class ColorMark {
        int x, y; Color color; int seq;
        ColorMark(int x, int y, Color c, int s) { this.x=x; this.y=y; this.color=c; this.seq=s; }
    }
    static class TypeMark {
        int x, y; String type; int seq;
        TypeMark(int x, int y, String t, int s) { this.x=x; this.y=y; this.type=t; this.seq=s; }
    }
    final List<ColorMark> colorMarks = new ArrayList<>();
    final List<TypeMark> typeMarks = new ArrayList<>();

    private TextGrid() {}

    static List<String> readLines(InputStream in, String encoding) throws IOException {
        Reader r = (encoding == null) ? new InputStreamReader(in) : new InputStreamReader(in, encoding);
        BufferedReader br = new BufferedReader(r);
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) lines.add(line);
        return lines;
    }

    static List<String> linesFromText(String text) throws IOException {
        // Mimic BufferedReader semantics over the given string.
        BufferedReader br = new BufferedReader(new StringReader(text));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) lines.add(line);
        return lines;
    }

    static TextGrid fromLines(List<String> rawLines, int tabSize, boolean html) {
        if (!rawLines.isEmpty()) {
            boolean allZero = true;
            for (String s : rawLines) if (s.length() != 0) { allZero = false; break; }
            if (allZero) throw new FakeCrash(FakeCrash.allEmptyLines(html));
        }
        if (tabSize <= 0) {
            for (String s : rawLines) if (s.indexOf('\t') >= 0) throw new FakeCrash(FakeCrash.tabsCrash(html));
        }
        List<String> lines = new ArrayList<>();
        for (String s : rawLines) lines.add(fixTabs(s, tabSize));

        while (lines.size() > 1 && isBlankAscii(lines.get(lines.size() - 1))) {
            lines.remove(lines.size() - 1);
        }
        if (lines.isEmpty()) lines.add("");
        int maxw = 0;
        for (String s : lines) maxw = Math.max(maxw, s.length());
        TextGrid g = new TextGrid();
        g.width = maxw + 4;
        g.height = lines.size() + 4;
        g.cells = new char[g.height][g.width];
        for (int y = 0; y < g.height; y++) Arrays.fill(g.cells[y], ' ');
        for (int y = 0; y < lines.size(); y++) {
            String s = lines.get(y);
            for (int x = 0; x < s.length(); x++) g.cells[y + 2][x + 2] = s.charAt(x);
        }
        g.original = copyCells(g.cells);
        g.extractColorCodes();
        g.extractTypeTags();
        return g;
    }

    static char[][] copyCells(char[][] in) {
        char[][] out = new char[in.length][];
        for (int i = 0; i < in.length; i++) out[i] = in[i].clone();
        return out;
    }

    static String fixTabs(String s, int tabSize) {
        if (s.indexOf('\t') < 0) return s;
        StringBuilder sb = new StringBuilder();
        int col = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\t') {
                int spaces = tabSize - (col % tabSize);
                for (int k = 0; k < spaces; k++) sb.append(' ');
                col += spaces;
            } else {
                sb.append(c);
                col++;
            }
        }
        return sb.toString();
    }

    static boolean isBlankAscii(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c!=' ' && c!='\t' && c!='\n' && c!='\u000B' && c!='\f' && c!='\r') return false;
        }
        return true;
    }

    char at(int x, int y) {
        if (x < 0 || y < 0 || x >= width || y >= height) return ' ';
        return cells[y][x];
    }
    char atOriginal(int x, int y) {
        if (x < 0 || y < 0 || x >= width || y >= height) return ' ';
        return original[y][x];
    }

    private void extractColorCodes() {
        int seq = 0;
        for (int y = 0; y < height; y++) {
            int x = 0;
            while (x < width) {
                if (cells[y][x] == 'c' && x + 3 < width) {
                    String code = new String(new char[]{cells[y][x+1], cells[y][x+2], cells[y][x+3]});
                    Color col = decodeColorCode(code);
