import java.awt.*;
import java.awt.geom.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;

class Diagram {
    final TextGrid grid;
    final Options opt;
    final boolean htmlContext;
    final int widthPx, heightPx;

    // directions: 0=N,1=E,2=S,3=W (clockwise in screen coords)
    static final int[] DX = {0, 1, 0, -1};
    static final int[] DY = {-1, 0, 1, 0};

    static class Vertex {
        int gx, gy, px, py;
        char ch;
        boolean roundSlash;
        Vertex(int gx, int gy, int px, int py, char ch) { this.gx=gx; this.gy=gy; this.px=px; this.py=py; this.ch=ch; }
    }

    static class Edge {
        int u, v; boolean horiz; boolean dashedUnit; boolean bridge;
        Edge(int u, int v, boolean h, boolean d) { this.u=u; this.v=v; this.horiz=h; this.dashedUnit=d; }
        int other(int x) { return x == u ? v : u; }
    }

    static class FP {
        float x, y;
        boolean control;
        boolean duplicate;
        FP(float x, float y) { this.x=x; this.y=y; }
    }

    static class DShape {
        static final int NORMAL = 0, ARROWHEAD = 1, MARKER = 2;
        int kind = NORMAL;
        boolean geometricClosed = false;
        boolean dashed = false;
        Color fillColor = null;
        String specialType = null; // d,s,o,mo,c,tr,io
        Shape awt = null;
        // for closed shapes
        List<Vertex> rawCycle;      // CCW (final) order
        List<Vertex> kept;          // kept vertices (final order)
        List<Boolean> segCommon;    // segCommon[i] = segment kept[i]->kept[i+1]
        List<Vertex> cornerOnly;    // direction-change vertices (raw)
        List<FP> finalPoints;       // for normal shapes (closed or open)
        int boundsMinX, boundsMinY, boundsMaxX, boundsMaxY;
        boolean isFilled() { return geometricClosed && !dashed; }
    }

    static class DText {
        String text;
        int gridX, gridY;   // area start in grid coords
        int cellLen;
        int rawStartX;      // token start (before bullet expansion)
        int x, y;           // draw point
        int fontSize;
        int textWidth;
        int align = 0; // 0 centre, 1 left, 2 right
        Color color = Color.BLACK;
    }

    final List<DShape> shapes = new ArrayList<>();
    final List<DShape> closedShapes = new ArrayList<>();
    final List<DText> texts = new ArrayList<>();

    // graph state
    private List<Vertex> vertices = new ArrayList<>();
    private int[][] vertexId;
    private List<Edge> edges = new ArrayList<>();
    private List<List<Integer>> adj = new ArrayList<>();
    private Map<Long, Integer> edgeIndexByPair = new HashMap<>();
    private boolean[][] inGraph;
    private boolean[][] isLineCell;
    private boolean[][] isVTextArrow;

    Diagram(TextGrid grid, Options opt, boolean htmlContext) {
        this.grid = grid; this.opt = opt; this.htmlContext = htmlContext;
        this.widthPx = grid.width * opt.cellWidth;
        this.heightPx = grid.height * opt.cellHeight;
        buildGraph();
        computeBridges();
        List<DShape> closed = extractFaces();
        closedShapes.addAll(closed);
        List<DShape> open = extractOpenShapes();
        List<DShape> arrows = extractArrows();
        List<DShape> markers = extractMarkers();
        // Prepare closed shapes (kept points) so marks can be assigned
        for (DShape s : closed) prepareClosedKept(s);
        assignMarks(closed);
        for (DShape s : closed) buildClosedAwt(s);
        shapes.addAll(closed);
        shapes.addAll(arrows);
        shapes.addAll(open);
        shapes.addAll(markers);
        extractTexts();
    }

    // ---------- graph classification ----------

    private boolean isLineChar(char c) { return c=='-'||c=='='||c=='|'||c==':'; }
    private boolean isCandidateChar(char c) { return c=='+'||c=='*'||c=='/'||c=='\\'||c=='<'||c=='>'||c=='^'; }

    private void buildGraph() {
        int W = grid.width, H = grid.height;
        vertexId = new int[H][W];
        for (int y=0;y<H;y++) Arrays.fill(vertexId[y], -1);
        inGraph = new boolean[H][W];
        isLineCell = new boolean[H][W];
        isVTextArrow = new boolean[H][W];
        boolean[][] isVShape = new boolean[H][W];
        boolean[][] isCandidate = new boolean[H][W];
        // candidateAllow[y][x][dir]
        boolean[][][] allow = new boolean[H][W][4];

        for (int y=0;y<H;y++) for (int x=0;x<W;x++) {
            char c = grid.cells[y][x];
            isLineCell[y][x] = isLineChar(c);
            if ((c=='v'||c=='V') && y>0) {
                char above = grid.cells[y-1][x];
                if (above=='|'||above==':') isVTextArrow[y][x] = true;
                if (above=='|'||above==':'||above=='*') isVShape[y][x] = true;
            }
            isCandidate[y][x] = isCandidateChar(c) || isVShape[y][x];
        }

        // helper to test whether a neighbour cell can connect back
        // First set allow for non-slash candidates
        for (int y=0;y<H;y++) for (int x=0;x<W;x++) {
            if (!isCandidate[y][x]) continue;
            char c = grid.cells[y][x];
            if (c!='/' && c!='\\') {
                Arrays.fill(allow[y][x], true);
            }
        }
        // Slash allowed pairs
        boolean[][] slashOk = new boolean[H][W];
        for (int y=0;y<H;y++) for (int x=0;x<W;x++) {
            char c = grid.cells[y][x];
            if (c!='/' && c!='\\') continue;
            boolean canN = canConnect(x, y-1, 2, isLineCell, isCandidate);
            boolean canE = canConnect(x+1, y, 3, isLineCell, isCandidate);
            boolean canS = canConnect(x, y+1, 0, isLineCell, isCandidate);
            boolean canW = canConnect(x-1, y, 1, isLineCell, isCandidate);
            boolean pair1, pair2;
            if (c=='/') { pair1 = canE && canS; pair2 = canW && canN; }
            else { pair1 = canW && canS; pair2 = canE && canN; }
            if (c=='/') {
                if (pair1) { allow[y][x][1]=true; allow[y][x][2]=true; }
                if (pair2) { allow[y][x][3]=true; allow[y][x][0]=true; }
            } else {
                if (pair1) { allow[y][x][3]=true; allow[y][x][2]=true; }
                if (pair2) { allow[y][x][1]=true; allow[y][x][0]=true; }
            }
            slashOk[y][x] = pair1 || pair2;
        }

        // Decide inclusion
        for (int y=0;y<H;y++) for (int x=0;x<W;x++) {
            char c = grid.cells[y][x];
            if (isLineCell[y][x]) { inGraph[y][x] = true; continue; }
            if (!isCandidate[y][x]) continue;
            if (c=='<'||c=='>'||c=='^') { inGraph[y][x]=true; continue; }
            if (isVShape[y][x]) { inGraph[y][x]=true; continue; }
            int cnt = 0;
            for (int d=0;d<4;d++) if (allow[y][x][d] && canConnect(x+DX[d], y+DY[d], (d+2)%4, isLineCell, isCandidate)) cnt++;
            if (c=='*') inGraph[y][x] = cnt >= 1;
            else if (c=='+') inGraph[y][x] = cnt >= 2;
            else if (c=='/'||c=='\\') inGraph[y][x] = slashOk[y][x];
        }

        // Create vertices
        for (int y=0;y<H;y++) for (int x=0;x<W;x++) {
            if (!inGraph[y][x]) continue;
            int px = x * opt.cellWidth + opt.cellWidth/2;
            int py = y * opt.cellHeight + opt.cellHeight/2;
            Vertex v = new Vertex(x, y, px, py, grid.cells[y][x]);
            if ((v.ch=='/'||v.ch=='\\') && slashOk[y][x]) v.roundSlash = true;
            vertexId[y][x] = vertices.size();
            vertices.add(v);
            adj.add(new ArrayList<>());
        }
        // Edges: east and south
        for (int y=0;y<H;y++) for (int x=0;x<W;x++) {
            int id = vertexId[y][x];
            if (id < 0) continue;
            // east
            if (x+1 < W && vertexId[y][x+1] >= 0) {
                if (allowsDir(x,y,1,isLineCell,allow) && allowsDir(x+1,y,3,isLineCell,allow)) {
                    boolean dash = grid.cells[y][x]=='=' || grid.cells[y][x+1]=='=';
                    addEdge(id, vertexId[y][x+1], true, dash);
                }
            }
            if (y+1 < H && vertexId[y+1][x] >= 0) {
                if (allowsDir(x,y,2,isLineCell,allow) && allowsDir(x,y+1,0,isLineCell,allow)) {
                    boolean dash = grid.cells[y][x]==':' || grid.cells[y+1][x]==':';
                    addEdge(id, vertexId[y+1][x], false, dash);
                }
            }
        }
    }

    private boolean allowsDir(int x, int y, int dir, boolean[][] isLine, boolean[][][] allow) {
        char c = grid.cells[y][x];
        if (isLine[y][x]) {
            if (dir==1||dir==3) return c=='-'||c=='=';
            else return c=='|'||c==':';
        }
        return allow[y][x][dir];
    }

    private boolean canConnect(int nx, int ny, int dirBack, boolean[][] isLine, boolean[][] isCand) {
        if (nx<0||ny<0||nx>=grid.width||ny>=grid.height) return false;
        char c = grid.cells[ny][nx];
        if (isLine[ny][nx]) {
            if (dirBack==1||dirBack==3) return c=='-'||c=='=';
            else return c=='|'||c==':';
        }
        // A 'v' that is only a text letter is not in isCand (isCand for v set only when isVShape)
        return isCand[ny][nx];
    }

    private void addEdge(int u, int v, boolean horiz, boolean dash) {
        int id = edges.size();
        edges.add(new Edge(u, v, horiz, dash));
        adj.get(u).add(id);
        adj.get(v).add(id);
        long key = ((long)Math.min(u,v) << 32) | (Math.max(u,v) & 0xffffffffL);
        edgeIndexByPair.put(key, id);
    }

    private Integer findEdge(int u, int v) {
        long key = ((long)Math.min(u,v) << 32) | (Math.max(u,v) & 0xffffffffL);
        return edgeIndexByPair.get(key);
    }

    private int degreeIn(int v, boolean bridgesOnly) {
        int d=0;
        for (int ei : adj.get(v)) if (!bridgesOnly || edges.get(ei).bridge) d++;
        return d;
    }

    // ---------- bridges (iterative DFS) ----------

    private void computeBridges() {
        int n = vertices.size();
        int[] disc = new int[n];
        int[] low = new int[n];
        int timer = 0;
        class Frame { int v; int parentEdge; int idx; Frame(int v,int p){this.v=v;this.parentEdge=p;} }
        for (int s=0;s<n;s++) {
            if (disc[s]!=0) continue;
            if (adj.get(s).isEmpty()) { disc[s]=low[s]=++timer; continue; }
            ArrayDeque<Frame> stack = new ArrayDeque<>();
            disc[s]=low[s]=++timer;
            stack.push(new Frame(s,-1));
            while (!stack.isEmpty()) {
                Frame f = stack.peek();
                int v = f.v;
                if (f.idx < adj.get(v).size()) {
                    int ei = adj.get(v).get(f.idx++);
                    if (ei == f.parentEdge) continue;
                    int to = edges.get(ei).other(v);
                    if (disc[to]!=0) {
                        low[v] = Math.min(low[v], disc[to]);
                    } else {
                        disc[to]=low[to]=++timer;
                        stack.push(new Frame(to, ei));
                    }
                } else {
                    stack.pop();
                    if (f.parentEdge!=-1 && !stack.isEmpty()) {
                        int parent = stack.peek().v;
                        low[parent] = Math.min(low[parent], low[v]);
                        if (low[v] > disc[parent]) edges.get(f.parentEdge).bridge = true;
                    }
                }
            }
        }
    }

    // ---------- faces ----------

    private Integer nonBridgeEdgeFrom(int v, int dir) {
        int gx = vertices.get(v).gx + DX[dir];
        int gy = vertices.get(v).gy + DY[dir];
        if (gx<0||gy<0||gx>=grid.width||gy>=grid.height) return null;
        int to = vertexId[gy][gx];
        if (to<0) return null;
        Integer ei = findEdge(v, to);
        if (ei==null || edges.get(ei).bridge) return null;
        return ei;
    }

    private List<DShape> extractFaces() {
        List<DShape> result = new ArrayList<>();
        int m = edges.size();
        boolean[] visitedDir = new boolean[m*2];
        // iterate vertices row-major (vertices list already row-major), dirs E,S,W,N
        int[] dirOrder = {1,2,3,0};
        for (int startV=0; startV<vertices.size(); startV++) {
            for (int d0 : dirOrder) {
                Integer ei0 = nonBridgeEdgeFrom(startV, d0);
                if (ei0==null) continue;
                int to0 = edges.get(ei0).other(startV);
                int dirId = ei0*2 + (edges.get(ei0).u==startV ? 0 : 1); // 0: u->v, 1: v->u
                if (visitedDir[dirId]) continue;
                // walk
                List<Integer> cycVerts = new ArrayList<>();
                List<Integer> cycEdges = new ArrayList<>();
                int curEdge = ei0;
                int curFrom = startV;
                int curDirId = dirId;
                boolean ok = true;
                int guard = 0;
                while (!visitedDir[curDirId]) {
                    visitedDir[curDirId]=true;
                    cycVerts.add(curFrom);
                    cycEdges.add(curEdge);
                    int curTo = edges.get(curEdge).other(curFrom);
                    int inDir = dirBetween(curFrom, curTo);
                    int rev = (inDir+2)%4;
                    Integer nextEdge = null; int nextFrom = curTo;
                    for (int delta=1; delta<=4; delta++) {
                        int nd = ((rev - delta) % 4 + 4) % 4;
                        Integer cand = nonBridgeEdgeFrom(curTo, nd);
                        if (cand!=null) { nextEdge=cand; break; }
                    }
                    if (nextEdge==null) { ok=false; break; }
                    curEdge = nextEdge; curFrom = nextFrom;
                    curDirId = curEdge*2 + (edges.get(curEdge).u==curFrom ? 0 : 1);
                    if (++guard > m*2+10) { ok=false; break; }
                }
                if (!ok || cycVerts.size()<4) continue;
                long area = 0;
                for (int i=0;i<cycVerts.size();i++) {
                    Vertex a = vertices.get(cycVerts.get(i));
                    Vertex b = vertices.get(cycVerts.get((i+1)%cycVerts.size()));
                    area += (long)a.gx * b.gy - (long)b.gx * a.gy;
                }
                if (area <= 0) continue;
                // Build shape, reverse to CCW (reference-like)
                DShape s = new DShape();
                s.geometricClosed = true;
                List<Vertex> revList = new ArrayList<>();
                revList.add(vertices.get(cycVerts.get(0)));
                for (int i=cycVerts.size()-1;i>=1;i--) revList.add(vertices.get(cycVerts.get(i)));
                s.rawCycle = revList;
                boolean dash=false;
                for (int ei : cycEdges) if (edges.get(ei).dashedUnit) dash=true;
                s.dashed = dash;
                result.add(s);
            }
        }
        // compute common edges count later in prepare
        return result;
    }

    private int dirBetween(int fromV, int toV) {
        Vertex a = vertices.get(fromV), b = vertices.get(toV);
        int dx = b.gx-a.gx, dy = b.gy-a.gy;
        for (int d=0;d<4;d++) if (DX[d]==dx && DY[d]==dy) return d;
        return -1;
    }

    private Map<Integer,Integer> commonEdgeCounts() {
        Map<Integer,Integer> counts = new HashMap<>();
        for (DShape s : closedShapes) {
            List<Vertex> c = s.rawCycle;
            for (int i=0;i<c.size();i++) {
                Vertex a=c.get(i), b=c.get((i+1)%c.size());
                Integer ei = findEdge(vertexId[a.gy][a.gx], vertexId[b.gy][b.gx]);
                if (ei!=null) counts.merge(ei,1,Integer::sum);
            }
        }
        return counts;
    }

    private void prepareClosedKept(DShape s) {
        // common counts computed once for all (closedShapes already filled)
        // (recomputed per shape; diagrams are small)
        Map<Integer,Integer> counts = commonEdgeCounts();
        List<Vertex> c = s.rawCycle;
        int n = c.size();
        List<Vertex> kept = new ArrayList<>();
        List<Integer> keptRawIdx = new ArrayList<>();
        for (int i=0;i<n;i++) {
            Vertex prev = c.get((i-1+n)%n), cur = c.get(i), next = c.get((i+1)%n);
            int dPrev = dirBetween(vertexId[prev.gy][prev.gx], vertexId[cur.gy][cur.gx]);
            int dNext = dirBetween(vertexId[cur.gy][cur.gx], vertexId[next.gy][next.gx]);
            Integer ePrev = findEdge(vertexId[prev.gy][prev.gx], vertexId[cur.gy][cur.gx]);
            Integer eNext = findEdge(vertexId[cur.gy][cur.gx], vertexId[next.gy][next.gx]);
            boolean cPrev = ePrev!=null && counts.getOrDefault(ePrev,0)>=2;
            boolean cNext = eNext!=null && counts.getOrDefault(eNext,0)>=2;
            if (dPrev != dNext || cPrev != cNext) { kept.add(cur); keptRawIdx.add(i); }
        }
        if (kept.isEmpty()) kept.addAll(c);
        s.kept = kept;
        s.segCommon = new ArrayList<>();
        for (int i=0;i<kept.size();i++) {
            Vertex a = kept.get(i);
            // first raw vertex after a in cycle
            int rawIdx = c.indexOf(a);
            Vertex b = c.get((rawIdx+1)%n);
            Integer ei = findEdge(vertexId[a.gy][a.gx], vertexId[b.gy][b.gx]);
            s.segCommon.add(ei!=null && counts.getOrDefault(ei,0)>=2);
        }
        // corner-only
        List<Vertex> corners = new ArrayList<>();
        for (int i=0;i<n;i++) {
            Vertex prev = c.get((i-1+n)%n), cur = c.get(i), next = c.get((i+1)%n);
            int dPrev = dirBetween(vertexId[prev.gy][prev.gx], vertexId[cur.gy][cur.gx]);
            int dNext = dirBetween(vertexId[cur.gy][cur.gx], vertexId[next.gy][next.gx]);
            if (dPrev != dNext) corners.add(cur);
        }
        s.cornerOnly = corners;
    }

    private boolean isRectangle(DShape s) {
        if (s.cornerOnly==null || s.cornerOnly.size()!=4) return false;
        Set<Integer> xs=new HashSet<>(), ys=new HashSet<>();
        for (Vertex v: s.cornerOnly) { xs.add(v.gx); ys.add(v.gy); }
        return xs.size()==2 && ys.size()==2;
    }

    private double polygonAreaAbs(List<FP> pts) {
        double a=0;
        for (int i=0;i<pts.size();i++){ FP p=pts.get(i), q=pts.get((i+1)%pts.size()); a += (double)p.x*q.y-(double)q.x*p.y; }
        return Math.abs(a);
    }

    // Final (separated) kept points as FP list (without round expansion)
    private List<FP> separatedKeptPoints(DShape s) {
        List<FP> out = new ArrayList<>();
        int n = s.kept.size();
        for (int i=0;i<n;i++) {
            Vertex v = s.kept.get(i);
            int[] xy = separatedPoint(s, i, v.px, v.py, true, true);
            out.add(new FP(xy[0], xy[1]));
        }
        return out;
    }

    // offset a point based on common segments prev/next (flags say which to consider)
    private int[] separatedPoint(DShape s, int keptIdx, int ox, int oy, boolean usePrev, boolean useNext) {
        if (opt.noSeparation) return new int[]{ox,oy};
        int nx=ox, ny=oy;
        float sep = opt.cellWidth / 5f;
        int n = s.kept.size();
        // prev segment: kept[keptIdx-1] -> kept[keptIdx], its segCommon index is keptIdx-1
        if (usePrev) {
            int prevIdx = (keptIdx-1+n)%n;
            if (s.segCommon.get(prevIdx)) {
                Vertex a=s.kept.get(prevIdx), b=s.kept.get(keptIdx);
                int dx=Integer.signum(b.gx-a.gx), dy=Integer.signum(b.gy-a.gy);
                int ix=dy, iy=-dx;
                if (ix!=0) nx=(int)(ox + ix*sep);
                if (iy!=0) ny=(int)(oy + iy*sep);
            }
        }
        if (useNext) {
            if (s.segCommon.get(keptIdx)) {
                Vertex a=s.kept.get(keptIdx), b=s.kept.get((keptIdx+1)%n);
                int dx=Integer.signum(b.gx-a.gx), dy=Integer.signum(b.gy-a.gy);
                int ix=dy, iy=-dx;
                if (ix!=0) nx=(int)(ox + ix*sep);
                if (iy!=0) ny=(int)(oy + iy*sep);
            }
        }
        return new int[]{nx,ny};
    }

    private void assignMarks(List<DShape> closed) {
        // Build a polygon shape per closed shape from separated kept points
        Map<DShape, Shape> polys = new HashMap<>();
        Map<DShape, Double> areas = new HashMap<>();
        for (DShape s: closed) {
            List<FP> pts = separatedKeptPoints(s);
            GeneralPath p = new GeneralPath();
            if (!pts.isEmpty()) {
                p.moveTo(pts.get(0).x, pts.get(0).y);
                for (int i=1;i<pts.size();i++) p.lineTo(pts.get(i).x, pts.get(i).y);
                p.closePath();
            }
            polys.put(s,p);
            areas.put(s, polygonAreaAbs(pts));
            int minx=Integer.MAX_VALUE,miny=Integer.MAX_VALUE,maxx=Integer.MIN_VALUE,maxy=Integer.MIN_VALUE;
            for (FP f: pts){ minx=Math.min(minx,(int)f.x); miny=Math.min(miny,(int)f.y); maxx=Math.max(maxx,(int)f.x); maxy=Math.max(maxy,(int)f.y); }
            s.boundsMinX=minx; s.boundsMinY=miny; s.boundsMaxX=maxx; s.boundsMaxY=maxy;
        }
        for (TextGrid.ColorMark m: grid.colorMarks) {
            int px = m.x*opt.cellWidth + opt.cellWidth/2;
            int py = m.y*opt.cellHeight + opt.cellHeight/2;
            DShape best=null; double bestArea=Double.MAX_VALUE;
            for (DShape s: closed) {
                if (polys.get(s).contains(px,py) && areas.get(s)<bestArea) { best=s; bestArea=areas.get(s); }
            }
            if (best!=null) best.fillColor = m.color;
        }
        for (TextGrid.TypeMark m: grid.typeMarks) {
            int px = m.x*opt.cellWidth + opt.cellWidth/2;
            int py = m.y*opt.cellHeight + opt.cellHeight/2;
            DShape best=null; double bestArea=Double.MAX_VALUE;
            for (DShape s: closed) {
                if (polys.get(s).contains(px,py) && areas.get(s)<bestArea) { best=s; bestArea=areas.get(s); }
            }
            if (best!=null) best.specialType = m.type;
        }
    }

    private void buildClosedAwt(DShape s) {
        if (s.specialType!=null && isRectangle(s)) {
            s.awt = buildSpecial(s);
            return;
        }
        // Expand round corners
        List<FP> pts = new ArrayList<>();
        int n = s.kept.size();
        for (int i=0;i<n;i++) {
            Vertex v = s.kept.get(i);
            Vertex prev = s.kept.get((i-1+n)%n), next = s.kept.get((i+1)%n);
            int dPrev = dirBetween(vertexId[prev.gy][prev.gx], vertexId[v.gy][v.gx]);
            int dNext = dirBetween(vertexId[v.gy][v.gx], vertexId[next.gy][next.gx]);
            boolean isCorner = dPrev != dNext;
            boolean round = isCorner && (opt.roundCorners || v.roundSlash);
            boolean prevRound = false;
            {
                Vertex pv = prev;
                Vertex pp = s.kept.get((i-2+n)%n);
                int dp1 = dirBetween(vertexId[pp.gy][pp.gx], vertexId[pv.gy][pv.gx]);
                int dp2 = dirBetween(vertexId[pv.gy][pv.gx], vertexId[v.gy][v.gx]);
                prevRound = (dp1!=dp2) && (opt.roundCorners || pv.roundSlash);
            }
            if (!round) {
                int[] xy = separatedPoint(s, i, v.px, v.py, true, true);
                FP f = new FP(xy[0], xy[1]);
                if (prevRound && i>=2) f.duplicate=true;
                pts.add(f);
            } else {
                // nearPrev
                int npx = v.px, npy = v.py;
                // toward prev: direction from v to prev is opposite dPrev
                int backDir = (dPrev+2)%4;
                if (backDir==1||backDir==3) npx += DX[backDir]*(opt.cellWidth/2); else npy += DY[backDir]*(opt.cellHeight/2);
                int[] xy1 = separatedPoint(s, i, npx, npy, true, false);
                FP f1 = new FP(xy1[0], xy1[1]);
                if (prevRound && i>=2) f1.duplicate=true;
                pts.add(f1);
                int[] xyc = separatedPoint(s, i, v.px, v.py, true, true);
                FP fc = new FP(xyc[0], xyc[1]); fc.control=true; pts.add(fc);
                int nnx=v.px, nny=v.py;
                if (dNext==1||dNext==3) nnx += DX[dNext]*(opt.cellWidth/2); else nny += DY[dNext]*(opt.cellHeight/2);
                int[] xy2 = separatedPoint(s, i, nnx, nny, false, true);
                pts.add(new FP(xy2[0], xy2[1]));
            }
        }
        s.finalPoints = pts;
        s.awt = buildPath(pts, true);
    }

    private Shape buildPath(List<FP> pts, boolean closed) {
        GeneralPath p = new GeneralPath();
        if (pts.isEmpty()) return p;
        p.moveTo(pts.get(0).x, pts.get(0).y);
        int i=1;
        while (i<pts.size()) {
            FP f = pts.get(i);
            if (f.control) {
                FP nxt = (i+1<pts.size()) ? pts.get(i+1) : pts.get(0);
                p.quadTo(f.x, f.y, nxt.x, nxt.y);
                i += 2;
            } else {
                p.lineTo(f.x, f.y);
                if (f.duplicate) p.lineTo(f.x, f.y);
                i++;
            }
        }
        if (closed) p.closePath();
        return p;
    }

    private Shape buildSpecial(DShape s) {
        float minX=s.boundsMinX, minY=s.boundsMinY, maxX=s.boundsMaxX, maxY=s.boundsMaxY;
        float w = maxX-minX, h = maxY-minY;
        float midX=(minX+maxX)/2f, midY=(minY+maxY)/2f;
        GeneralPath p = new GeneralPath();
        switch (s.specialType) {
            case "d": {
                int dx = (int)(w/6);
                int dy = (int)(h/8);
                p.moveTo(minX,minY);
                p.lineTo(maxX,minY);
                p.lineTo(maxX,maxY);
                p.quadTo(midX+dx, maxY-dy, midX, maxY);
                p.quadTo(midX-dx, maxY+dy, minX, maxY);
                p.closePath();
                return p;
            }
            case "s": {
                int dx = (int)(w/6);
                int topDy = opt.cellHeight/2;
                int botDy = opt.cellWidth;
                p.moveTo(minX,minY);
                p.curveTo(minX+dx, minY+topDy, maxX-dx, minY+topDy, maxX, minY);
                p.curveTo(maxX-dx, minY-topDy, minX+dx, minY-topDy, minX, minY);
                p.moveTo(minX,minY);
                p.lineTo(minX,maxY);
                p.curveTo(minX+dx, maxY+botDy, maxX-dx, maxY+botDy, maxX, maxY);
                p.lineTo(maxX,minY);
                return p;
            }
            case "o": {
                return ellipsePathTop(minX,minY,w,h);
            }
            case "c": {
                p.moveTo(minX,midY); p.lineTo(midX,minY); p.lineTo(maxX,midY); p.lineTo(midX,maxY); p.closePath();
                return p;
            }
            case "mo": case "tr": case "io": {
                float off = opt.fixedSlope ? h*0.125f : opt.cellWidth/2f;
                if (s.specialType.equals("mo")) {
                    p.moveTo(minX-off,minY); p.lineTo(maxX+off,minY); p.lineTo(maxX-off,maxY); p.lineTo(minX+off,maxY);
                } else if (s.specialType.equals("tr")) {
                    p.moveTo(minX+off,minY); p.lineTo(maxX-off,minY); p.lineTo(maxX+off,maxY); p.lineTo(minX-off,maxY);
                } else {
                    p.moveTo(minX+off,minY); p.lineTo(maxX+off,minY); p.lineTo(maxX-off,maxY); p.lineTo(minX-off,maxY);
                }
                p.closePath();
                return p;
            }
            default:
                p.moveTo(minX,minY); p.lineTo(minX,maxY); p.lineTo(maxX,maxY); p.lineTo(maxX,minY); p.closePath();
                return p;
        }
    }

    static Shape ellipsePathTop(float x, float y, float w, float h) {
        Ellipse2D.Float e = new Ellipse2D.Float(x,y,w,h);
        PathIterator it = e.getPathIterator(null);
        List<float[]> segs = new ArrayList<>();
        List<Integer> types = new ArrayList<>();
        float[] c = new float[6];
        while (!it.isDone()) { int t=it.currentSegment(c); types.add(t); segs.add(c.clone()); it.next(); }
        // segs: 0 move(right),1 cubic->bottom,2 cubic->left,3 cubic->top,4 cubic->right,5 close
        GeneralPath p = new GeneralPath();
        if (segs.size()>=5) {
            float[] top = segs.get(3);
            p.moveTo(top[4], top[5]);
            int[] order = {4,1,2,3};
            for (int idx: order) { float[] s=segs.get(idx); p.curveTo(s[0],s[1],s[2],s[3],s[4],s[5]); }
            p.closePath();
        }
        return p;
    }

    // ---------- open shapes ----------

    private List<DShape> extractOpenShapes() {
        List<DShape> result = new ArrayList<>();
        boolean[] visited = new boolean[edges.size()];
        // arms from non-degree-2 vertices
        for (int start=0; start<vertices.size(); start++) {
            int deg = degreeIn(start, true);
            if (deg==0 || deg==2) continue;
            for (int ei : adj.get(start)) {
                if (!edges.get(ei).bridge || visited[ei]) continue;
                List<Vertex> path = walkArm(start, ei, visited);
                if (path.size()>=2) result.add(makeOpenShape(path));
            }
        }
        // remaining components (all degree 2, or isolated paths whose endpoints degree1 but start loop missed? degree1 handled)
        for (int ei=0; ei<edges.size(); ei++) {
            if (!edges.get(ei).bridge || visited[ei]) continue;
            int start = edges.get(ei).u;
            List<Vertex> path = walkArm(start, ei, visited);
            if (path.size()>=2) result.add(makeOpenShape(path));
        }
        // stubs
        for (int y=0;y<grid.height;y++) for (int x=0;x<grid.width;x++) {
            char c = grid.cells[y][x];
            if (c!='-' && c!='|') continue;
            int id = vertexId[y][x];
            if (id<0) continue;
            if (degreeIn(id,false)!=0) continue;
            DShape s = new DShape();
            s.geometricClosed=false;
            List<FP> pts = new ArrayList<>();
            int px = x*opt.cellWidth + opt.cellWidth/2;
            int py = y*opt.cellHeight + opt.cellHeight/2;
            if (c=='-') { pts.add(new FP(x*opt.cellWidth, py)); pts.add(new FP(x*opt.cellWidth+opt.cellWidth-1, py)); }
            else { pts.add(new FP(px, y*opt.cellHeight)); pts.add(new FP(px, y*opt.cellHeight+opt.cellHeight-1)); }
            s.finalPoints = pts;
            s.awt = buildPath(pts,false);
            result.add(s);
        }
        return result;
    }

    private List<Vertex> walkArm(int start, int firstEdge, boolean[] visited) {
        List<Vertex> path = new ArrayList<>();
        path.add(vertices.get(start));
        int cur = start;
        int prevEdge = -1;
        int e = firstEdge;
        while (true) {
            visited[e]=true;
            int nxt = edges.get(e).other(cur);
            path.add(vertices.get(nxt));
            prevEdge = e; cur = nxt;
            if (degreeIn(cur,true)!=2) break;
            int ne=-1;
            for (int cand: adj.get(cur)) if (edges.get(cand).bridge && cand!=prevEdge) { ne=cand; break; }
            if (ne==-1) break;
            e = ne;
            if (visited[e]) break;
        }
        return path;
    }

    private DShape makeOpenShape(List<Vertex> raw) {
        DShape s = new DShape();
        s.geometricClosed=false;
        boolean dash=false;
        for (int i=0;i+1<raw.size();i++) {
            Integer ei = findEdge(vertexId[raw.get(i).gy][raw.get(i).gx], vertexId[raw.get(i+1).gy][raw.get(i+1).gx]);
            if (ei!=null && edges.get(ei).dashedUnit) dash=true;
        }
        s.dashed=dash;
        // kept points
        List<Vertex> kept = new ArrayList<>();
        for (int i=0;i<raw.size();i++) {
            if (i==0||i==raw.size()-1) { kept.add(raw.get(i)); continue; }
            int d1 = dirBetween(vertexId[raw.get(i-1).gy][raw.get(i-1).gx], vertexId[raw.get(i).gy][raw.get(i).gx]);
            int d2 = dirBetween(vertexId[raw.get(i).gy][raw.get(i).gx], vertexId[raw.get(i+1).gy][raw.get(i+1).gx]);
            if (d1!=d2) kept.add(raw.get(i));
        }
        List<FP> pts = new ArrayList<>();
        for (int i=0;i<kept.size();i++) {
            Vertex v = kept.get(i);
            boolean internal = i>0 && i<kept.size()-1;
            boolean round = internal && (opt.roundCorners || v.roundSlash);
            boolean prevRound=false;
            if (i>=2) {
                Vertex pv = kept.get(i-1);
                boolean pvInternal = (i-1)>0 && (i-1)<kept.size()-1;
                prevRound = pvInternal && (opt.roundCorners || pv.roundSlash);
            }
            if (!round) {
                FP f = new FP(v.px, v.py);
                if (prevRound) f.duplicate=true;
                pts.add(f);
            } else {
                Vertex prev = kept.get(i-1), next = kept.get(i+1);
                int dPrev = dirBetween(vertexId[prev.gy][prev.gx], vertexId[v.gy][v.gx]);
                int dNext = dirBetween(vertexId[v.gy][v.gx], vertexId[next.gy][next.gx]);
                int back=(dPrev+2)%4;
                int npx=v.px, npy=v.py;
                if (back==1||back==3) npx += DX[back]*(opt.cellWidth/2); else npy += DY[back]*(opt.cellHeight/2);
                FP f1=new FP(npx,npy); if (prevRound) f1.duplicate=true; pts.add(f1);
                FP fc=new FP(v.px,v.py); fc.control=true; pts.add(fc);
                int nnx=v.px, nny=v.py;
                if (dNext==1||dNext==3) nnx += DX[dNext]*(opt.cellWidth/2); else nny += DY[dNext]*(opt.cellHeight/2);
                pts.add(new FP(nnx,nny));
            }
        }
        s.finalPoints = pts;
        s.awt = buildPath(pts,false);
        return s;
    }

    // ---------- arrows & markers ----------

    private List<DShape> extractArrows() {
        List<DShape> out = new ArrayList<>();
        for (int y=0;y<grid.height;y++) for (int x=0;x<grid.width;x++) {
            char c = grid.cells[y][x];
            int dir=-1; // tip direction: 0 N,1 E,2 S,3 W
            if (c=='^') dir=0;
            else if (c=='>') dir=1;
            else if (c=='<') dir=3;
            else if ((c=='v'||c=='V') && y>0 && (grid.cells[y-1][x]=='|'||grid.cells[y-1][x]==':'||grid.cells[y-1][x]=='*')) {
                // only if this cell is in graph (star case requires star to be on a line; inGraph check)
                if (inGraph[y][x]) {
                    // For '*' above: require star itself to have a vertical edge to v (i.e. edge exists)
                    if (grid.cells[y-1][x]=='*') {
                        int vid = vertexId[y][x]; int aid = (y-1>=0)? vertexId[y-1][x]:-1;
                        if (vid>=0 && aid>=0 && findEdge(vid,aid)!=null) dir=2;
                    } else dir=2;
                }
            }
            if (dir<0) continue;
            DShape s = new DShape();
            s.kind = DShape.ARROWHEAD;
            s.geometricClosed = true; // filled, but not a "closed shape" for shadow purposes; kind distinguishes
            int left=x*opt.cellWidth, top=y*opt.cellHeight, right=left+opt.cellWidth, bottom=top+opt.cellHeight;
            int cx=left+opt.cellWidth/2, cy=top+opt.cellHeight/2;
            GeneralPath p=new GeneralPath();
            if (dir==0) { p.moveTo(cx,top); p.lineTo(left,bottom); p.lineTo(right,bottom); }
            else if (dir==2) { p.moveTo(left,top); p.lineTo(cx,bottom); p.lineTo(right,top); }
            else if (dir==3) { p.moveTo(right,top); p.lineTo(left,cy); p.lineTo(right,bottom); }
            else { p.moveTo(left,top); p.lineTo(right,cy); p.lineTo(left,bottom); }
            p.closePath();
            s.awt=p;
            out.add(s);
        }
        return out;
    }

    private List<DShape> extractMarkers() {
        List<DShape> out = new ArrayList<>();
        for (int y=0;y<grid.height;y++) for (int x=0;x<grid.width;x++) {
            if (grid.cells[y][x]!='*') continue;
            int id = vertexId[y][x];
            if (id<0 || degreeIn(id,false)==0) continue;
            DShape s=new DShape();
            s.kind=DShape.MARKER;
            s.geometricClosed=true;
            int px = x*opt.cellWidth + opt.cellWidth/2;
            int py = y*opt.cellHeight + opt.cellHeight/2;
            float d = opt.cellWidth * 0.7f;
            s.awt = new Ellipse2D.Float(px-d/2, py-d/2, d, d);
            out.add(s);
        }
        return out;
    }

    // ---------- texts ----------

    private static Graphics2D dummyG;
    private static final Map<Integer,FontMetrics> fmCache = new HashMap<>();
    static FontMetrics metrics(int size) {
        FontMetrics fm = fmCache.get(size);
        if (fm==null) {
            if (dummyG==null) {
                BufferedImage img = new BufferedImage(1,1,BufferedImage.TYPE_INT_RGB);
                dummyG = img.createGraphics();
            }
            fm = dummyG.getFontMetrics(new Font("Dialog", Font.BOLD, size));
            fmCache.put(size,fm);
        }
        return fm;
    }
    static int stringWidth(String s, int size) { return metrics(size).stringWidth(s); }

    private void extractTexts() {
        // Build text grid
        char[][] tg = TextGrid.copyCells(grid.cells);
        // bullet markers from original grid
        boolean[][] bulletAt = new boolean[grid.height][grid.width]; // indexed by token start cell
        for (int y=0;y<grid.height;y++) {
            for (int x=1;x+2<grid.width;x++) {
                char c = grid.atOriginal(x,y);
                if ((c=='o'||c=='*') && grid.atOriginal(x-1,y)==' ' && grid.atOriginal(x+1,y)==' ' && grid.atOriginal(x+2,y)!=' ') {
                    bulletAt[y][x+2]=true;
                    if (c=='o') tg[y][x]=' ';
                }
            }
        }
        for (int y=0;y<grid.height;y++) for (int x=0;x<grid.width;x++) {
            char c = tg[y][x];
            if (c=='-'||c=='='||c=='|'||c==':'||c=='*'||c=='<'||c=='>'||c=='^') tg[y][x]=' ';
            else if ((c=='v'||c=='V') && isVTextArrow[y][x]) tg[y][x]=' ';
            else if (c=='+') {
                if (inGraph[y][x] || hasLineNeighbour(x,y)) tg[y][x]=' ';
            }
            else if ((c=='/'||c=='\\') && inGraph[y][x]) tg[y][x]=' ';
        }

        List<DText> raw = new ArrayList<>();
        for (int y=0;y<grid.height;y++) {
            int x=0;
            while (x<grid.width) {
                if (tg[y][x]==' ') { x++; continue; }
                int start=x;
                int lastNonSpace=x;
                int i=x;
                while (i<grid.width) {
                    if (tg[y][i]==' ') {
                        if (i+1>=grid.width || tg[y][i+1]==' ') break;
                    } else lastNonSpace=i;
                    i++;
                }
                int endExclusive = lastNonSpace+1;
                String token = new String(tg[y], start, endExclusive-start);
                DText t = new DText();
                t.gridY=y; t.rawStartX=start;
                if (bulletAt[y][start]) {
                    t.text = "\u2022" + token;
                    t.gridX = start-1;
                    t.cellLen = endExclusive - (start-1);
                } else if (token.length()==1) {
                    t.text = token + " ";
                    t.gridX = start;
                    t.cellLen = 2;
                } else {
                    t.text = token;
                    t.gridX = start;
                    t.cellLen = endExclusive-start;
                }
                raw.add(t);
                x = i;
            }
        }

        if (opt.defaultFontSize<=0 && !raw.isEmpty()) {
            throw new FakeCrash(FakeCrash.fontCrash(htmlContext));
        }

        // metrics
        for (DText t: raw) {
            int size = opt.defaultFontSize;
            int alloc = t.cellLen * opt.cellWidth;
            while (size>1 && stringWidth(t.text, size) > alloc) size--;
            t.fontSize=size;
            t.textWidth=stringWidth(t.text, size);
        }
        applyAlignment(raw);
        for (DText t: raw) {
            int areaLeft = t.gridX * opt.cellWidth;
            int alloc = t.cellLen * opt.cellWidth;
            int top = t.gridY * opt.cellHeight;
            FontMetrics fm = metrics(t.fontSize);
            int baseline = top + (int)Math.round((opt.cellHeight + fm.getAscent() - fm.getDescent())/2.0);
            t.y = baseline;
            if (t.align==1) t.x = areaLeft;
            else if (t.align==2) t.x = areaLeft + alloc - t.textWidth;
            else t.x = areaLeft + alloc/2 - t.textWidth/2;
            t.color = colorForText(t, areaLeft, alloc, top);
            texts.add(t);
        }
    }

    private boolean hasLineNeighbour(int x,int y) {
        for (int d=0;d<4;d++) {
            int nx=x+DX[d], ny=y+DY[d];
            if (nx>=0&&ny>=0&&nx<grid.width&&ny<grid.height&&isLineCell[ny][nx]) return true;
        }
        return false;
    }

    private void applyAlignment(List<DText> raw) {
        int n=raw.size();
        int[] parent=new int[n];
        for (int i=0;i<n;i++) parent[i]=i;
        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            public int applyAsInt(int a){ return a; }
        };
        // union-find via simple loops
        for (int i=0;i<n;i++) for (int j=i+1;j<n;j++) {
            DText a=raw.get(i), b=raw.get(j);
            if (Math.abs(a.gridY-b.gridY)==1) {
                int a0=a.gridX, a1=a.gridX+a.cellLen, b0=b.gridX, b1=b.gridX+b.cellLen;
                if (Math.min(a1,b1) > Math.max(a0,b0)) {
                    int ra=i; while(parent[ra]!=ra) ra=parent[ra];
                    int rb=j; while(parent[rb]!=rb) rb=parent[rb];
                    if (ra!=rb) parent[rb]=ra;
                }
            }
        }
        Map<Integer,List<DText>> groups=new HashMap<>();
        for (int i=0;i<n;i++){ int r=i; while(parent[r]!=r) r=parent[r]; groups.computeIfAbsent(r,k->new ArrayList<>()).add(raw.get(i)); }
        for (List<DText> g: groups.values()) {
            if (g.size()<2) continue;
            // left clusters
            Map<Integer,List<DText>> byStart=new HashMap<>();
            for (DText t:g) byStart.computeIfAbsent(t.gridX,k->new ArrayList<>()).add(t);
            for (List<DText> cl: byStart.values()) {
                if (cl.size()<2) continue;
                Set<Integer> ends=new HashSet<>(); for (DText t:cl) ends.add(t.gridX+t.cellLen);
                if (ends.size()>=2) for (DText t:cl) t.align=1;
            }
            Map<Integer,List<DText>> byEnd=new HashMap<>();
            for (DText t:g) byEnd.computeIfAbsent(t.gridX+t.cellLen,k->new ArrayList<>()).add(t);
            for (List<DText> cl: byEnd.values()) {
                if (cl.size()<2) continue;
                Set<Integer> starts=new HashSet<>(); for (DText t:cl) starts.add(t.gridX);
                if (starts.size()>=2) for (DText t:cl) if (t.align==0) t.align=2;
            }
        }
    }

    private Color colorForText(DText t, int areaLeft, int alloc, int top) {
        double cx = areaLeft + alloc/2.0;
        double cy = top + opt.cellHeight/2.0;
        DShape best=null; double bestArea=Double.MAX_VALUE;
        for (DShape s: shapes) {
            if (s.awt==null) continue;
            boolean filled = (s.kind==DShape.ARROWHEAD) || (s.kind==DShape.MARKER) || (s.kind==DShape.NORMAL && s.isFilled());
            if (!filled) continue;
            if (s.awt.contains(cx,cy)) {
                Rectangle b = s.awt.getBounds();
                double area = (double)b.width*b.height;
                if (area<bestArea) { bestArea=area; best=s; }
            }
        }
        if (best==null) return Color.BLACK;
        Color fill;
        if (best.kind==DShape.ARROWHEAD) fill=Color.BLACK;
        else if (best.kind==DShape.MARKER) fill=Color.WHITE;
        else fill = best.fillColor!=null ? best.fillColor : Color.WHITE;
        int max = Math.max(fill.getRed(), Math.max(fill.getGreen(), fill.getBlue()));
        return max < 204 ? Color.WHITE : Color.BLACK;
    }
