class BitmapRenderer {
    static BufferedImage renderToImage(Diagram d, Options o) {
        int type = o.effectiveBackground().getAlpha() < 255 ? BufferedImage.TYPE_INT_ARGB : BufferedImage.TYPE_INT_RGB;
        BufferedImage image = new BufferedImage(d.widthPx, d.heightPx, type);
