            } else if (s.kind == Diagram.DShape.MARKER) {
                g.setColor(Color.WHITE);
                g.fill(s.awt);
                g.setColor(Color.BLACK);
                g.setStroke(normalStroke);
                g.draw(s.awt);
            } else if ("s".equals(s.specialType)) {
                if (s.isFilled()) {
                    g.setColor(s.fillColor != null ? s.fillColor : Color.WHITE);
                    g.fill(s.awt);
                }
                g.setColor(Color.BLACK);
                g.setStroke(s.dashed ? dashedStroke : normalStroke);
                g.draw(s.awt);
            } else if (s.isFilled()) {
                g.setColor(s.fillColor != null ? s.fillColor : Color.WHITE);
                g.fill(s.awt);
                g.setColor(Color.BLACK);
                g.setStroke(s.dashed ? dashedStroke : normalStroke);
                g.draw(s.awt);
            } else {
                g.setColor(Color.BLACK);
                g.setStroke(s.dashed ? dashedStroke : normalStroke);
                g.draw(s.awt);
            }
        }

        for (Diagram.DText t : d.texts) {
            g.setColor(t.color);
            g.setFont(new Font("Dialog", Font.BOLD, t.fontSize));
            g.drawString(t.text, t.x, t.y);
        }

        if (o.debug) {
            if (o.cellWidth > 0 && o.cellHeight > 0) {
                g.setStroke(new BasicStroke(1));
                g.setXORMode(Color.BLACK);
                g.setColor(new Color(85, 85, 85));
