    private static BufferedImage makeShadow(Diagram d, Options o, int type) {
        BufferedImage shadow = new BufferedImage(d.widthPx, d.heightPx, type);
        Graphics2D g = shadow.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, o.antialias ? RenderingHints.VALUE_ANTIALIAS_ON : RenderingHints.VALUE_ANTIALIAS_OFF);
        g.setColor(o.effectiveBackground());
