        return sb.toString();
    }

    static String hex(Color c) {
        return String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
    }

    static String pathData(Shape shape) {
        StringBuilder sb = new StringBuilder();
        PathIterator it = shape.getPathIterator(null);
        float[] coords = new float[6];
        while (!it.isDone()) {
            int type = it.currentSegment(coords);
            switch (type) {
                case PathIterator.SEG_MOVETO:
                    sb.append('M').append(coords[0]).append(' ').append(coords[1]).append(' ');
                    break;
                case PathIterator.SEG_LINETO:
                    sb.append('L').append(coords[0]).append(' ').append(coords[1]).append(' ');
                    break;
                case PathIterator.SEG_QUADTO:
                    sb.append('Q').append(coords[0]).append(' ').append(coords[1]).append(' ').append(coords[2]).append(' ').append(coords[3]).append(' ');
                    break;
                case PathIterator.SEG_CUBICTO:
                    sb.append('C').append(coords[0]).append(' ').append(coords[1]).append(' ').append(coords[2]).append(' ').append(coords[3]).append(' ').append(coords[4]).append(' ').append(coords[5]).append(' ');
                    break;
                case PathIterator.SEG_CLOSE:
                    sb.append('z');
                    break;
            }
            it.next();
        }
        return sb.toString();
    }
