import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.*;
import javax.imageio.ImageIO;

public class Main {
    private static long startMillis;

    static class Def {
        String sn; String ln; boolean hasArg;
        Def(String sn, String ln, boolean h) { this.sn=sn; this.ln=ln; this.hasArg=h; }
    }
    static final List<Def> DEFS = new ArrayList<>();
    static final List<Def> CANDIDATE_ORDER = new ArrayList<>();
    static Def defByLong(String ln) { for (Def d: DEFS) if (d.ln.equals(ln)) return d; return null; }
    static Def defByShort(String sn) { for (Def d: DEFS) if (sn.equals(d.sn)) return d; return null; }
    static {
        DEFS.add(new Def(null, "help", false));
        DEFS.add(new Def("A", "no-antialias", false));
        DEFS.add(new Def("b", "background", true));
        DEFS.add(new Def("d", "debug", false));
        DEFS.add(new Def("E", "no-separation", false));
        DEFS.add(new Def("e", "encoding", true));
        DEFS.add(new Def("h", "html", false));
        DEFS.add(new Def("o", "overwrite", false));
        DEFS.add(new Def("r", "round-corners", false));
        DEFS.add(new Def("S", "no-shadows", false));
        DEFS.add(new Def("s", "scale", true));
        DEFS.add(new Def(null, "svg", false));
        DEFS.add(new Def(null, "svg-font-url", true));
        DEFS.add(new Def("T", "transparent", false));
        DEFS.add(new Def("t", "tabs", true));
        DEFS.add(new Def("v", "verbose", false));
        DEFS.add(new Def("W", "fixed-slope", false));
        String[] order = {"help","verbose","overwrite","no-shadows","no-antialias","fixed-slope","debug","round-corners","no-separation","html","transparent","encoding","scale","tabs","background","svg","svg-font-url"};
        for (String s: order) CANDIDATE_ORDER.add(defByLong(s));
    }

    static class Occ { Def def; String value; Occ(Def d,String v){def=d;value=v;} }
    static class ParseResult {
        List<Occ> occ = new ArrayList<>();
        List<String> pos = new ArrayList<>();
        boolean has(String ln) { for (Occ o: occ) if (o.def.ln.equals(ln)) return true; return false; }
        String first(String ln) { for (Occ o: occ) if (o.def.ln.equals(ln)) return o.value; return null; }
    }
    static class ParseError extends Exception { ParseError(String m){super(m);} }

    public static void main(String[] args) throws Exception {
        startMillis = System.currentTimeMillis();
        try {
            run(args);
        } catch (FakeCrash fc) {
            System.err.print(fc.stderrText);
            System.exit(1);
        }
    }

    static void run(String[] args) throws Exception {
        if (args.length == 0) {
            System.out.print(HelpText.UPPER);
            return;
        }
        ParseResult pr;
        try {
            pr = parse(args);
        } catch (ParseError e) {
            System.err.println(e.getMessage());
            System.out.print(HelpText.UPPER);
            System.exit(2);
            return;
        }
        if (pr.has("help")) {
            System.out.print(HelpText.UPPER);
            return;
        }
        Options o = buildOptions(pr);
        if (pr.pos.isEmpty()) {
            System.err.println("Error: Please provide the input file filename");
            System.out.print(HelpText.LOWER);
            System.exit(2);
            return;
        }
        String in = pr.pos.get(0);
        String outArg = pr.pos.size() > 1 ? pr.pos.get(1) : null;
        if (o.html) {
            printBanner(pr);
            htmlConvert(in, outArg, o);
            return;
        }
        String out;
        if (outArg != null) out = outArg;
        else if (in.equals("-")) out = "-";
        else out = makeTargetFilename(in, o.svg, o.overwrite);
        boolean toStdout = out.equals("-");
        if (!toStdout) printBanner(pr);
        if (!toStdout) {
            if (in.equals("-")) System.out.println("Reading standard input");
            else System.out.println("Reading file: " + in);
        }
        TextGrid grid;
        try {
            InputStream is = in.equals("-") ? System.in : new FileInputStream(in);
            List<String> lines;
            try { lines = TextGrid.readLines(is, o.encoding); }
            finally { if (!in.equals("-")) { try { is.close(); } catch (IOException ignored) {} } }
            grid = TextGrid.fromLines(lines, o.tabs, false);
        } catch (FileNotFoundException e) {
            System.err.println("Error: File " + in + " does not exist");
            System.exit(1);
            return;
        }
        if (o.debug) {
            if (!toStdout) System.out.println("Using grid:");
            System.out.print(grid.debugString());
            System.out.flush();
        }
        Diagram diagram = new Diagram(grid, o, false);
        if (!toStdout) System.out.println("Rendering to file: " + out);
        try {
            if (o.svg) {
                String svg = SVGRenderer.render(diagram, o);
                if (toStdout) {
                    System.out.write(svg.getBytes(StandardCharsets.UTF_8));
                    System.out.flush();
                } else {
                    try (FileOutputStream fos = new FileOutputStream(out)) { fos.write(svg.getBytes(StandardCharsets.UTF_8)); }
                }
            } else {
                BufferedImage img = BitmapRenderer.renderToImage(diagram, o);
                if (toStdout) {
                    ImageIO.write(img, "png", System.out);
                    System.out.flush();
                } else {
                    ImageIO.write(img, "png", new File(out));
                }
            }
        } catch (IOException e) {
            System.err.println("Error: Cannot write to file " + out);
            System.exit(1);
            return;
        }
        if (!toStdout) {
            long secs = (System.currentTimeMillis() - startMillis) / 1000;
            System.out.println("Done in " + secs + "sec");
        }
    }

    static void printBanner(ParseResult pr) {
        System.out.println();
        System.out.println("ditaa version 0.11, Copyright (C) 2004--2017  Efstathios (Stathis) Sideris");
        System.out.println();
        System.out.println("Running with options:");
        for (Occ o : pr.occ) {
            if (o.def.hasArg) System.out.println(o.def.ln + " = " + o.value);
            else System.out.println(o.def.ln);
        }
    }

    static Options buildOptions(ParseResult pr) {
        Options o = new Options();
        try {
            if (pr.has("scale")) o.scale = Float.parseFloat(pr.first("scale"));
            if (pr.has("background")) o.background = parseBackground(pr.first("background"));
            if (pr.has("tabs")) o.tabs = Integer.parseInt(pr.first("tabs"));
        } catch (RuntimeException e) {
            System.err.println("Error: " + e.getMessage());
            System.out.print(HelpText.UPPER);
            System.exit(2);
        }
        if (pr.has("encoding")) {
            o.encoding = pr.first("encoding");
            try { Charset.forName(o.encoding); }
            catch (RuntimeException e) {
                System.err.println("Error: " + e.getMessage());
                System.exit(2);
            }
        }
        o.antialias = !pr.has("no-antialias");
        o.debug = pr.has("debug");
        o.noSeparation = pr.has("no-separation");
        o.html = pr.has("html");
        o.overwrite = pr.has("overwrite");
        o.roundCorners = pr.has("round-corners");
        o.noShadows = pr.has("no-shadows");
        o.svg = pr.has("svg");
        if (pr.has("svg-font-url")) o.svgFontUrl = pr.first("svg-font-url");
        o.transparent = pr.has("transparent");
        o.verbose = pr.has("verbose");
        o.fixedSlope = pr.has("fixed-slope");
        o.computeDerived();
        return o;
    }

    static Color parseBackground(String bg) {
        if (bg.length() != 6 && bg.length() != 8) {
            throw new IllegalArgumentException("Cannot interpret \"" + bg + "\" as background colour. It needs to be a 6- or 8-digit hex number, depending on whether you have transparency or not (same as HTML).");
        }
        if (bg.length() == 6) {
            return new Color(Integer.parseInt(bg, 16));
        } else {
            int r = Integer.parseInt(bg.substring(0,2), 16);
            int g = Integer.parseInt(bg.substring(2,4), 16);
            int b = Integer.parseInt(bg.substring(4,6), 16);
            int a = Integer.parseInt(bg.substring(6,8), 16);
            return new Color(r, g, b, a);
        }
    }

    static String deriveBase(String in) {
        File f = new File(in);
        String name = f.getName();
        int dot = name.lastIndexOf('.');
        if (dot >= 0) name = name.substring(0, dot);
        String parent = f.getParent();
        if (parent == null) return name;
        return new File(parent).getAbsolutePath() + File.separator + name;
    }

    static String makeTargetFilename(String in, boolean svg, boolean overwrite) {
        String base = deriveBase(in);
        String ext = svg ? ".svg" : ".png";
        String target = base + ext;
        if (!overwrite) {
            int counter = 2;
            while (new File(target).exists()) {
                target = base + "_" + counter + ext;
                counter++;
            }
        }
        return target;
    }

    // ---------- CLI parsing ----------

    static List<Def> matchingLongs(String name) {
        List<Def> out = new ArrayList<>();
        for (Def d : DEFS) if (d.ln.equals(name)) { out.add(d); return out; }
        for (Def d : CANDIDATE_ORDER) if (d.ln.startsWith(name)) out.add(d);
        return out;
    }

    static String ambiguousMsg(String display, List<Def> matches) {
        StringBuilder sb = new StringBuilder();
        sb.append("Ambiguous option: '").append(display).append("'  (could be: ");
        for (int i=0;i<matches.size();i++) { if (i>0) sb.append(", "); sb.append("'").append(matches.get(i).ln).append("'"); }
        sb.append(")");
        return sb.toString();
    }

    static boolean isNegativeNumber(String tok) {
        if (!tok.startsWith("-") || tok.length()<2) return false;
        char c = tok.charAt(1);
        if (!(Character.isDigit(c) || c=='.')) return false;
        try { Double.parseDouble(tok); return true; } catch (Exception e) { return false; }
    }

    static boolean looksLikeOption(String tok) {
        if (tok.equals("-") || tok.equals("--")) return false;
        if (!tok.startsWith("-") || tok.length()==1) return false;
        if (isNegativeNumber(tok)) return false;
        if (tok.startsWith("--")) {
            String name = tok.substring(2);
            int eq = name.indexOf('=');
            if (eq>=0) name = name.substring(0,eq);
            return matchingLongs(name).size()==1;
        } else {
            String body = tok.substring(1);
            if (body.length()>1 && matchingLongs(body).size()==1) return true;
            return defByShort(body.substring(0,1)) != null;
        }
    }

    static ParseResult parse(String[] args) throws ParseError {
        ParseResult pr = new ParseResult();
        boolean endOpts = false;
        for (int i=0;i<args.length;i++) {
            String tok = args[i];
            if (endOpts) { pr.pos.add(tok); continue; }
            if (tok.equals("--")) { endOpts=true; continue; }
            if (tok.equals("-") || !tok.startsWith("-") || tok.length()==1) { pr.pos.add(tok); continue; }
            if (tok.startsWith("--")) {
                String body = tok.substring(2);
                i = handleLong(pr, args, i, tok, "--", body);
            } else {
                String body = tok.substring(1);
                if (body.length()>1) {
                    List<Def> m = matchingLongs(body);
                    if (m.size()>1) throw new ParseError(ambiguousMsg(tok, m));
                    if (m.size()==1) {
                        // single-dash long option (no '=' possible here because then matching would be 0)
                        i = handleLong(pr, args, i, tok, "-", body);
                        continue;
                    }
                }
                // burst short options
                for (int j=0;j<body.length();j++) {
                    String sn = body.substring(j,j+1);
                    Def def = defByShort(sn);
                    if (def==null) throw new ParseError("Unrecognized option: " + tok);
                    if (def.hasArg) {
                        String rest = body.substring(j+1);
                        String val;
                        if (!rest.isEmpty()) val = rest;
                        else {
                            if (i+1>=args.length || looksLikeOption(args[i+1])) throw new ParseError("Missing argument for option: " + (def.sn!=null?def.sn:def.ln));
                            val = args[++i];
                        }
                        pr.occ.add(new Occ(def,val));
                        break;
                    } else {
                        pr.occ.add(new Occ(def,null));
                    }
                }
            }
        }
        return pr;
    }

    static int handleLong(ParseResult pr, String[] args, int i, String originalTok, String prefix, String body) throws ParseError {
        String name = body;
        String eqVal = null;
        int eq = body.indexOf('=');
        if (eq>=0) { name = body.substring(0,eq); eqVal = body.substring(eq+1); }
        List<Def> m = matchingLongs(name);
        if (m.isEmpty()) throw new ParseError("Unrecognized option: " + originalTok);
        if (m.size()>1) throw new ParseError(ambiguousMsg(prefix+name, m));
        Def def = m.get(0);
        if (def.hasArg) {
            String val;
            if (eqVal!=null) val = eqVal;
            else {
                if (i+1>=args.length || looksLikeOption(args[i+1])) throw new ParseError("Missing argument for option: " + (def.sn!=null?def.sn:def.ln));
                val = args[++i];
            }
            pr.occ.add(new Occ(def,val));
        } else {
            pr.occ.add(new Occ(def,null));
            if (eqVal!=null) pr.pos.add(eqVal);
        }
        return i;
    }

    // ---------- HTML mode ----------

    static class PreEl {
        int start, end;
        String inner;
        String id; // null if absent / no value
    }

    static void htmlConvert(String in, String outArg, Options o) throws Exception {
        String out = outArg != null ? outArg : deriveBase(in) + "_processed.html";
        if (!o.overwrite && new File(out).exists()) {
            System.out.println("Error: File " + out + " exists. If you would like to overwrite it, please use the --overwrite option.");
            return;
        }
        String content;
        try {
            InputStream is = new FileInputStream(in);
            List<String> lines;
            try { lines = TextGrid.readLines(is, o.encoding); }
            finally { try { is.close(); } catch (IOException ignored) {} }
            if (lines.isEmpty()) content = "";
            else content = String.join("\n", lines) + "\n";
        } catch (IOException e) {
            System.err.println("Error: cannot read file " + in);
            return;
        }
        System.out.print("Converting HTML file (" + in + " -> " + out + ")... ");
        List<PreEl> pres = parsePres(content);
        if (pres.isEmpty()) {
            System.out.println("\nHTML document does not contain any <pre> tags with their class attribute set to \"textdiagram\". Nothing to do.");
            return;
        }
        String imagesDirPath = new File(out).getParent() + File.separator + "images";
        String ext = o.svg ? "svg" : "png";
        HashMap<String,String> diagrams = new HashMap<>();
        StringBuilder newContent = new StringBuilder();
        int counter = 0;
        int lastEnd = 0;
        for (PreEl pre : pres) {
            newContent.append(content, lastEnd, pre.start);
            String filename;
            if (pre.id != null) filename = pre.id + "." + ext;
            else { counter++; filename = "ditaa_diagram_" + counter + "." + ext; }
            String imagePath = imagesDirPath + File.separator + filename;
            diagrams.put(imagePath, pre.inner);
            newContent.append("<img src=\"images/").append(filename).append("\" />");
            lastEnd = pre.end;
        }
        newContent.append(content, lastEnd, content.length());
        try (FileOutputStream fos = new FileOutputStream(out)) {
            Charset cs = o.encoding != null ? Charset.forName(o.encoding) : Charset.defaultCharset();
            fos.write(newContent.toString().getBytes(cs));
        } catch (IOException e) {
            System.err.println("Error while writing to file " + out);
            return;
        }
        System.out.println("done");
        System.out.println("Generating diagrams... ");
        File imagesDirFile = new File(imagesDirPath);
        if (!imagesDirFile.exists()) {
            if (!imagesDirFile.mkdir()) {
                System.err.println("Could not create directory images");
                return;
            }
        }
        for (Map.Entry<String,String> entry : diagrams.entrySet()) {
            String imagePath = entry.getKey();
            File imageFile = new File(imagePath);
            String localName = imagePath.substring(imagesDirPath.length()+1);
            if (imageFile.exists() && !o.overwrite) {
                System.out.println("Error: Cannot overwrite file images/" + localName + ", file already exists. Use the --overwrite option if you would like to allow file overwrite.");
                continue;
            }
            List<String> lines = TextGrid.linesFromText(entry.getValue());
            TextGrid grid = TextGrid.fromLines(lines, o.tabs, true);
            Diagram diagram = new Diagram(grid, o, true);
            if (o.svg) {
                String svg = SVGRenderer.render(diagram, o);
                try (FileOutputStream fos = new FileOutputStream(imageFile)) {
                    fos.write(svg.getBytes(StandardCharsets.UTF_8));
                } catch (IOException e) {
                    System.err.println("Error: Cannot write to file " + in + " -- skipping");
                    continue;
                }
            } else {
                BufferedImage img = BitmapRenderer.renderToImage(diagram, o);
                try {
                    ImageIO.write(img, "png", imageFile);
                } catch (IOException e) {
                    e.printStackTrace();
                    System.err.println("Error: Cannot write to file " + in + " -- skipping");
                    continue;
                }
            }
            System.out.println("\t" + imagePath);
        }
        System.out.println("\n...done");
    }

    static String decodeEntities(String s) {
        StringBuilder sb = new StringBuilder();
        int i=0;
        while (i<s.length()) {
            char c=s.charAt(i);
            if (c=='&') {
                int semi=s.indexOf(';', i);
                if (semi>i && semi-i<=10) {
                    String ent=s.substring(i+1,semi);
                    String rep=null;
                    switch(ent) {
                        case "amp": rep="&"; break;
                        case "lt": rep="<"; break;
                        case "gt": rep=">"; break;
                        case "quot": rep="\""; break;
                        case "apos": rep="'"; break;
                        default:
                            try {
                                if (ent.startsWith("#x")||ent.startsWith("#X")) rep=String.valueOf((char)Integer.parseInt(ent.substring(2),16));
                                else if (ent.startsWith("#")) rep=String.valueOf((char)Integer.parseInt(ent.substring(1)));
                            } catch (Exception ignored) {}
                    }
                    if (rep!=null) { sb.append(rep); i=semi+1; continue; }
                }
            }
            sb.append(c); i++;
        }
        return sb.toString();
    }

    static List<PreEl> parsePres(String content) {
        List<PreEl> out = new ArrayList<>();
        int n = content.length();
        int i = 0;
        while (i < n) {
            int lt = content.indexOf('<', i);
            if (lt < 0) break;
            if (content.startsWith("<!--", lt)) {
                int e = content.indexOf("-->", lt+4);
                if (e<0) break;
                i = e+3; continue;
            }
            if (lt+1 < n && (content.charAt(lt+1)=='/' || content.charAt(lt+1)=='!' || content.charAt(lt+1)=='?')) {
                int gt = findTagEnd(content, lt);
                if (gt<0) break;
                i = gt+1; continue;
            }
            // tag name
            int p = lt+1;
            int nameStart=p;
            while (p<n && (Character.isLetterOrDigit(content.charAt(p)))) p++;
            if (p==nameStart) { i=lt+1; continue; }
            String tagName = content.substring(nameStart,p);
            int gt = findTagEnd(content, lt);
            if (gt<0) break;
            boolean selfClosing = false;
            {
                int q=gt-1;
                while (q>lt && Character.isWhitespace(content.charAt(q))) q--;
                if (q>lt && content.charAt(q)=='/') selfClosing=true;
            }
            if (!tagName.equalsIgnoreCase("pre")) { i = gt+1; continue; }
            // parse attributes between p and gt
            Map<String,String> attrs = new LinkedHashMap<>();
            Set<String> attrsNoValue = new HashSet<>();
            int a = p;
            while (a < gt) {
                while (a<gt && (Character.isWhitespace(content.charAt(a)) || content.charAt(a)=='/')) a++;
                if (a>=gt) break;
                int astart=a;
                while (a<gt && !Character.isWhitespace(content.charAt(a)) && content.charAt(a)!='=' && content.charAt(a)!='/' && content.charAt(a)!='>') a++;
                if (a==astart) { a++; continue; }
                String aname = content.substring(astart,a).toLowerCase(Locale.ENGLISH);
                while (a<gt && Character.isWhitespace(content.charAt(a))) a++;
                String aval=null;
                if (a<gt && content.charAt(a)=='=') {
                    a++;
                    while (a<gt && Character.isWhitespace(content.charAt(a))) a++;
                    if (a<gt && (content.charAt(a)=='"' || content.charAt(a)=='\'')) {
                        char quote=content.charAt(a); a++;
                        int vstart=a;
                        while (a<gt && content.charAt(a)!=quote) a++;
                        aval = content.substring(vstart, Math.min(a,gt));
                        if (a<gt) a++;
                    } else {
                        int vstart=a;
                        while (a<gt && !Character.isWhitespace(content.charAt(a)) && content.charAt(a)!='>' && content.charAt(a)!='/') a++;
                        aval = content.substring(vstart,a);
                    }
                    aval = decodeEntities(aval);
                } else {
                    attrsNoValue.add(aname);
                }
                if (!attrs.containsKey(aname) && aval!=null) attrs.put(aname, aval);
            }
            String cls = attrs.get("class");
            if (!"textdiagram".equals(cls)) { i = gt+1; continue; }
            PreEl pre = new PreEl();
            pre.start = lt;
            pre.id = attrs.getOrDefault("id", null);
            if (selfClosing) {
                pre.end = gt+1; pre.inner="";
            } else {
                int[] close = findClosingPre(content, gt+1);
                if (close==null) {
                    pre.end = gt+1; pre.inner="";
                } else {
                    pre.inner = content.substring(gt+1, close[0]);
                    pre.end = close[1]+1;
                }
            }
            out.add(pre);
            i = pre.end;
        }
        return out;
    }

    static int findTagEnd(String s, int lt) {
        char quote=0;
        for (int i=lt+1;i<s.length();i++) {
            char c=s.charAt(i);
            if (quote!=0) { if (c==quote) quote=0; }
            else if (c=='"'||c=='\'') quote=c;
            else if (c=='>') return i;
        }
        return -1;
    }

    static int[] findClosingPre(String s, int from) {
        String lower = s.toLowerCase(Locale.ENGLISH);
        int idx = from;
        while (true) {
            int p = lower.indexOf("</pre", idx);
            if (p<0) return null;
            int after = p+5;
            if (after>=s.length()) return null;
            char c = s.charAt(after);
            if (c=='>' || Character.isWhitespace(c)) {
                int gt = findTagEnd(s,p);
                if (gt<0) return null;
                return new int[]{p, gt};
            }
            idx = p+5;
        }
    }
