        DEFS.add(new Def("v", "verbose", false));
        DEFS.add(new Def("W", "fixed-slope", false));
        String[] order = {"help","verbose","overwrite","no-shadows","no-antialias","fixed-slope","debug","round-corners","no-separation","html","transparent","encoding","scale","tabs","background","svg","svg-font-url"};
        for (String s: order) CANDIDATE_ORDER.add(defByLong(s));
    }

    static class Occ { Def def; String value; Occ(Def d,String v){def=d;value=v;} }
    static class ParseResult {
        List<Occ> occ = new ArrayList<>();
        List<String> pos = new ArrayList<>();
        boolean has(String ln) { for (Occ o: occ) if (o.def.ln.equals(ln)) return true; return false; }
        String first(String ln) { for (Occ o: occ) if (o.def.ln.equals(ln)) return o.value; return null; }
    }
    static class ParseError extends Exception { ParseError(String m){super(m);} }

    public static void main(String[] args) throws Exception {
        startMillis = System.currentTimeMillis();
        try {
            run(args);
        } catch (FakeCrash fc) {
            System.err.print(fc.stderrText);
            System.exit(1);
        }
    }

    static void run(String[] args) throws Exception {
        if (args.length == 0) {
            System.out.print(HelpText.UPPER);
            return;
        }
        ParseResult pr;
        try {
            pr = parse(args);
        } catch (ParseError e) {
            System.err.println(e.getMessage());
            System.out.print(HelpText.UPPER);
            System.exit(2);
            return;
        }
        if (pr.has("help")) {
            System.out.print(HelpText.UPPER);
            return;
        }
        Options o = buildOptions(pr);
        if (pr.pos.isEmpty()) {
            System.err.println("Error: Please provide the input file filename");
            System.out.print(HelpText.LOWER);
            System.exit(2);
            return;
        }
        String in = pr.pos.get(0);
        String outArg = pr.pos.size() > 1 ? pr.pos.get(1) : null;
