        try {
            if (pr.has("scale")) o.scale = Float.parseFloat(pr.first("scale"));
            if (pr.has("background")) o.background = parseBackground(pr.first("background"));
            if (pr.has("tabs")) o.tabs = Integer.parseInt(pr.first("tabs"));
