                msgs.append(f"file {k} differ ({len(f1[k])} vs {len(f2[k])})\n"+"\n".join(diffs))
            ok=False
    print(("OK  " if ok else "FAIL")+" "+(label or repr(content)[:80])+" args="+repr(args))
    for m in msgs: print("   ",m)
    return ok

def pngdiffdesc(a,b):
    # write temp and compare pixels
    try:
        open('/tmp/ca.png','wb').write(a); open('/tmp/cb.png','wb').write(b)
        wa,ha,cta,bppa,pa=read_png('/tmp/ca.png'); wb,hb,ctb,bppb,pb=read_png('/tmp/cb.png')
        if (wa,ha,cta)!=(wb,hb,ctb): return f"dims/type ref {(wa,ha,cta)} our {(wb,hb,ctb)} len {len(a)}/{len(b)}"
        if bppa!=bppb: return f"bpp {bppa}/{bppb}"
        diff=0; maxd=0; total=wa*ha
        first=[]
        for i in range(total):
            va=tuple(pa[i*bppa:(i+1)*bppa]); vb=tuple(pb[i*bppb:(i+1)*bppb])
            if va!=vb:
                diff+=1; maxd=max(maxd,max(abs(va[j]-vb[j]) for j in range(min(len(va),len(vb)))))
                if len(first)<5: first.append((i%wa,i//wa,va,vb))
        return f"pixdiff {diff}/{total} ({100*diff/total:.2f}%) maxd={maxd} first={first} len {len(a)}/{len(b)}"
    except Exception as e:
        return f"pngparse err {e} len {len(a)}/{len(b)} md5 {hashlib.md5(a).hexdigest()[:8]}/{hashlib.md5(b).hexdigest()[:8]}"
