import java.awt.*; import java.awt.image.*; import java.util.*;
public class SearchFont{
 public static void main(String[] a){
  Map<Integer,Integer> obs=new TreeMap<>();
  int[][] pairs={{2,1},{3,2},{4,3},{5,4},{6,5},{7,7},{8,8},{9,9},{10,10},{11,11},{12,13},{13,14},{14,15},{15,16},{16,17},{17,18},{18,19},{19,21},{20,22},{21,23},{22,24},{23,25},{25,27},{26,28},{28,30},{29,31},{30,32},{32,35},{33,36},{35,38},{36,39},{37,40},{39,42},{40,43},{42,45},{43,46},{44,47},{46,50},{47,51},{49,53},{50,54},{51,55},{53,57},{54,58},{56,60},{57,61},{58,63},{60,65},{61,66},{63,68},{64,69},{65,70},{67,72},{68,73},{70,75}};
  for(int[] p:pairs) obs.put(p[0],p[1]);
  BufferedImage img=new BufferedImage(1,1,BufferedImage.TYPE_INT_RGB); Graphics2D g=img.createGraphics();
  int MAX=120;
  int[][] asc=new int[MAX+1][1]; int[] A=new int[MAX+1],D=new int[MAX+1],H=new int[MAX+1],MA=new int[MAX+1],MD=new int[MAX+1],ADV=new int[MAX+1];
  String[] samples={"a","m","M","W","x"," ","hello","abcdefghijklmnopqrstuvwxyz","ABCDEFGHIJKLMNOPQRSTUVWXYZ","0123456789","abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789","iiii","WWWW","oooo"};
  int[][] SW=new int[samples.length][MAX+1];
  for(int sz=1;sz<=MAX;sz++){FontMetrics fm=g.getFontMetrics(new Font("Dialog",Font.BOLD,sz)); A[sz]=fm.getAscent();D[sz]=fm.getDescent();H[sz]=fm.getHeight();MA[sz]=fm.getMaxAscent();MD[sz]=fm.getMaxDescent();ADV[sz]=fm.getMaxAdvance(); for(int i=0;i<samples.length;i++) SW[i][sz]=fm.stringWidth(samples[i]);}
  // Build feature list: each feature is an int array size MAX+1 with name
  List<int[]> feats=new ArrayList<>(); List<String> names=new ArrayList<>();
  feats.add(A);names.add("asc"); feats.add(D);names.add("desc"); feats.add(H);names.add("height"); feats.add(MA);names.add("maxasc"); feats.add(MD);names.add("maxdesc"); feats.add(ADV);names.add("maxadv");
  for(int i=0;i<samples.length;i++){feats.add(SW[i]);names.add("sw:"+samples[i]);}
  // combos asc + k*desc, height + k*desc etc
  for(int k=-3;k<=3;k++){int[] f=new int[MAX+1]; for(int sz=1;sz<=MAX;sz++)f[sz]=A[sz]+k*D[sz]; feats.add(f);names.add("asc+"+k+"desc");}
  for(int k=-3;k<=3;k++){int[] f=new int[MAX+1]; for(int sz=1;sz<=MAX;sz++)f[sz]=H[sz]+k*D[sz]; feats.add(f);names.add("h+"+k+"desc");}
  int best=0;
  for(int fi=0;fi<feats.size();fi++){
   int[] F=feats.get(fi);
   // precompute first index where F >= T for T up to max via pointer? brute over threshold params: threshold = (num*ch)/den + off, in scaled integer: compare F*den ? num*ch+off*den
   for(int num=0;num<=40;num++) for(int den=1;den<=20;den++){
     double ratio=(double)num/den; if(ratio>20) continue;
     for(int off=-20;off<=20;off++){
      for(int mode=0;mode<4;mode++){
       int ok=0;
       for(Map.Entry<Integer,Integer> e:obs.entrySet()){
         int ch=e.getKey(); int rhs=num*ch+off*den;
         int cand=-1;
         if(mode<2){ // first
           for(int sz=1;sz<=MAX;sz++){int lhs=F[sz]*den; if(mode==0?lhs>=rhs:lhs>rhs){cand=sz;break;}}
         } else {
           for(int sz=1;sz<=MAX;sz++){int lhs=F[sz]*den; if(mode==2?lhs<=rhs:lhs<rhs)cand=sz;}
         }
         if(cand==e.getValue()) ok++;
       }
       if(ok>best){best=ok; System.out.println("best "+ok+"/"+obs.size()+" feat="+names.get(fi)+" num="+num+" den="+den+" off="+off+" mode="+mode);}
       if(ok>=obs.size()-3) System.out.println("NEAR "+ok+" feat="+names.get(fi)+" num="+num+" den="+den+" off="+off+" mode="+mode);
      }
     }
   }
  }
  System.out.println("done best="+best);
 }
}
