new_prepare = """    private void prepareClosedKept(DShape s) {
        List<Vertex> c = s.rawCycle;
        int n = c.size();
        List<Vertex> corners = new ArrayList<>();
        for (int i=0;i<n;i++) {
            Vertex prev = c.get((i-1+n)%n), cur = c.get(i), next = c.get((i+1)%n);
            int dPrev = dirBetween(vertexId[prev.gy][prev.gx], vertexId[cur.gy][cur.gx]);
            int dNext = dirBetween(vertexId[cur.gy][cur.gx], vertexId[next.gy][next.gx]);
            if (dPrev != dNext) corners.add(cur);
        }
        if (corners.size() < 3) corners = new ArrayList<>(c);
        s.cornerOnly = corners;
        s.kept = corners;
        s.segCommon = new ArrayList<>();
        for (int i=0;i<corners.size();i++) s.segCommon.add(false);
    }

    private void computeSegCommon(List<DShape> closed) {
        // A segment (between corner points) of one shape is "common" with a
        // segment of another shape when they lie on the same grid line and
        // their spans overlap with positive length.
        for (int a=0;a<closed.size();a++) {
            for (int b=a+1;b<closed.size();b++) {
                DShape sa = closed.get(a), sb = closed.get(b);
                for (int i=0;i<sa.kept.size();i++) {
                    Vertex a1 = sa.kept.get(i), a2 = sa.kept.get((i+1)%sa.kept.size());
                    for (int j=0;j<sb.kept.size();j++) {
                        Vertex b1 = sb.kept.get(j), b2 = sb.kept.get((j+1)%sb.kept.size());
                        boolean common = false;
                        if (a1.gx==a2.gx && b1.gx==b2.gx && a1.gx==b1.gx) {
                            int lo = Math.max(Math.min(a1.gy,a2.gy), Math.min(b1.gy,b2.gy));
                            int hi = Math.min(Math.max(a1.gy,a2.gy), Math.max(b1.gy,b2.gy));
                            common = hi > lo;
                        } else if (a1.gy==a2.gy && b1.gy==b2.gy && a1.gy==b1.gy) {
                            int lo = Math.max(Math.min(a1.gx,a2.gx), Math.min(b1.gx,b2.gx));
                            int hi = Math.min(Math.max(a1.gx,a2.gx), Math.max(b1.gx,b2.gx));
                            common = hi > lo;
                        }
                        if (common) { sa.segCommon.set(i, true); sb.segCommon.set(j, true); }
                    }
                }
            }
        }
    }

"""
