public class ShAA {
 static BufferedImage render(boolean shadowAA){
   int W=140,H=126;
   BufferedImage src=new BufferedImage(W,H,BufferedImage.TYPE_INT_RGB);
   Graphics2D g=src.createGraphics();
   g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, shadowAA?RenderingHints.VALUE_ANTIALIAS_ON:RenderingHints.VALUE_ANTIALIAS_OFF);
   g.setColor(Color.WHITE); g.fillRect(0,0,W,H);
   g.translate(3.0,3.0);
   g.setColor(new Color(150,150,150));
   GeneralPath p=new GeneralPath();
