   g.fill(p); g.dispose();
   float[] d=new float[36]; Arrays.fill(d,1f/36);
   BufferedImage blur=new ConvolveOp(new Kernel(6,6,d),ConvolveOp.EDGE_NO_OP,null).filter(src,null);
   // draw main shape (no text) like renderer
   Graphics2D mg=blur.createGraphics();
   mg.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);
   mg.setColor(Color.WHITE); mg.fill(p);
   mg.setColor(Color.BLACK); mg.setStroke(new BasicStroke(1.0f,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND)); mg.draw(p);
   mg.dispose();
   return blur;
 }
